main.script:
(function () {
  'use strict';
  function $(s, c) { return (c || document).querySelector(s); }
  function $$(s, c) { return Array.prototype.slice.call((c || document).querySelectorAll(s)); }
  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
  function r1(v) { return Math.round(v * 10) / 10; }

  function init() {
    var page = $('.ab-page'); if (!page) return;
    var L = window.TRELayer || null;
    var R = L ? L.reduced : !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    var FINE = L ? L.fine : false;
    page.classList.add('ab-on');

    /* ---------- entrances: anything already on screen stays put; the rest settles in as it arrives ---------- */
    var hooks = $$('.ab-rv, .ab-win, .ab-groups, .ab-val, .ab-strip, .ab-office', page);
    if (R || !L || !('IntersectionObserver' in window)) {
      hooks.forEach(function (el) { el.classList.add('in'); });
    } else {
      var vh = window.innerHeight;
      hooks.forEach(function (el) { var r = el.getBoundingClientRect(); if (r.top < vh && r.bottom > 0) el.classList.add('in'); });
      page.classList.add('ab-live');
      hooks.forEach(function (el) {
        if (el.classList.contains('in')) return;
        L.onVisible(el, function (en, isIn) { if (isIn) el.classList.add('in'); }, { once: true, threshold: 0.16, rootMargin: '0px 0px -6% 0px' });
      });
    }

    tabs(page);
    timeline(page, L, R);
    strip(page, R);
    values(page, L, R, FINE);
  }

  /* ---------- the three disciplines as a segmented selector (keyboard: arrows, Home, End) ---------- */
  function tabs(page) {
    var box = $('.ab-creds', page), bar = box && $('.ab-tabs', box); if (!bar) return;
    var tabsEl = $$('.ab-tab', bar), ink = $('.ab-tab-ink', bar);
    var panels = tabsEl.map(function (t) { return document.getElementById(t.getAttribute('aria-controls')); });
    if (!panels.every(Boolean)) return;
    var cur = 0;
    bar.setAttribute('role', 'tablist');
    var h2 = $('.ab-bio-head h2', page); if (h2) { h2.id = h2.id || 'ab-bio-title'; bar.setAttribute('aria-labelledby', h2.id); }
    tabsEl.forEach(function (t, i) { t.setAttribute('role', 'tab'); panels[i].setAttribute('role', 'tabpanel'); panels[i].setAttribute('aria-labelledby', t.id); });
    box.classList.add('ab-tabs-live');
    function place() {
      var t = tabsEl[cur]; if (!t || !ink) return;
      ink.style.setProperty('--iw', t.offsetWidth + 'px');
      ink.style.setProperty('--ix', t.offsetLeft + 'px');
      ink.style.setProperty('--iy', (t.offsetTop + t.offsetHeight - 1) + 'px');
    }
    function select(i, focus) {
      cur = (i + tabsEl.length) % tabsEl.length;
      tabsEl.forEach(function (t, j) {
        var on = j === cur;
        t.setAttribute('aria-selected', on ? 'true' : 'false'); t.tabIndex = on ? 0 : -1;
        panels[j].classList.toggle('is-on', on); panels[j].tabIndex = on ? 0 : -1;
      });
      place(); if (focus) tabsEl[cur].focus();
    }
    tabsEl.forEach(function (t, i) { t.addEventListener('click', function () { select(i); }); });
    bar.addEventListener('keydown', function (e) {
      var n = null;
      if (e.key === 'ArrowRight') n = cur + 1; else if (e.key === 'ArrowLeft') n = cur - 1;
      else if (e.key === 'Home') n = 0; else if (e.key === 'End') n = tabsEl.length - 1;
      if (n === null) return; e.preventDefault(); select(n, true);
    });
    select(0);
    requestAnimationFrame(function () { requestAnimationFrame(function () { box.classList.add('ab-ink-on'); }); });
    window.addEventListener('resize', place, { passive: true });
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(place);
  }

  /* ---------- milestones: one line through the four years, drawn by the scroll (TRELayer.draw);
     a year lights up when the line reaches it ---------- */
  function timeline(page, L, R) {
    var tl = $('.ab-tl', page), list = tl && $('.ab-tl-list', tl); if (!list || !L || !L.draw) return;
    var items = $$('.ab-tl-item', list), dots = items.map(function (it) { return $('.ab-tl-dot', it); });
    if (items.length < 2) return;
    var NS = 'http://www.w3.org/2000/svg';
    var svg = document.createElementNS(NS, 'svg'), track = document.createElementNS(NS, 'path'), line = document.createElementNS(NS, 'path'), probe = document.createElementNS(NS, 'path');
    svg.setAttribute('class', 'ab-tl-svg'); svg.setAttribute('aria-hidden', 'true'); svg.setAttribute('focusable', 'false');
    track.setAttribute('class', 'ab-tl-track'); line.setAttribute('class', 'ab-tl-line'); probe.setAttribute('class', 'ab-tl-probe');
    svg.appendChild(track); svg.appendChild(line); svg.appendChild(probe);
    list.insertBefore(svg, list.firstChild);
    var fr = items.map(function () { return 0; });

    function build() {
      var b = list.getBoundingClientRect(); if (!b.width) return;
      var pts = dots.map(function (d) { var r = d.getBoundingClientRect(); return [r.left + r.width / 2 - b.left, r.top + r.height / 2 - b.top]; });
      var vert = Math.abs(pts[pts.length - 1][0] - pts[0][0]) < 2;
      var ys = pts.map(function (p) { return p[1]; }), top = Math.floor(Math.min.apply(null, ys) - 24), h = Math.ceil(Math.max.apply(null, ys) - top + 24);
      svg.style.top = top + 'px'; svg.setAttribute('width', Math.round(b.width)); svg.setAttribute('height', h);
      svg.setAttribute('viewBox', '0 0 ' + Math.round(b.width) + ' ' + h);
      /* a settled tremor line: gentle alternating arcs that pass through every year (C1-smooth at each node) */
      var P = pts.map(function (p) { return [p[0], p[1] - top]; }), segs = [], c = vert ? 0.034 : 0.03;
      for (var i = 1; i < P.length; i++) {
        var a = P[i - 1], z = P[i], s = i % 2 ? 1 : -1;
        if (vert) { var dy = (z[1] - a[1]) / 3, ox = s * c * (z[1] - a[1]); segs.push('C' + r1(a[0] + ox) + ' ' + r1(a[1] + dy) + ' ' + r1(z[0] + ox) + ' ' + r1(z[1] - dy) + ' ' + r1(z[0]) + ' ' + r1(z[1])); }
        else { var dx = (z[0] - a[0]) / 3, oy = s * c * (z[0] - a[0]); segs.push('C' + r1(a[0] + dx) + ' ' + r1(a[1] + oy) + ' ' + r1(z[0] - dx) + ' ' + r1(z[1] + oy) + ' ' + r1(z[0]) + ' ' + r1(z[1])); }
      }
      var m = 'M' + r1(P[0][0]) + ' ' + r1(P[0][1]), d = m + segs.join('');
      track.setAttribute('d', d); line.setAttribute('d', d);
      var len = line.getTotalLength() || 1;
      line.style.setProperty('--len', Math.ceil(len));
      fr = P.map(function (p, j) { if (!j) return 0; probe.setAttribute('d', m + segs.slice(0, j).join('')); return probe.getTotalLength() / len; });
      light();
    }
    /* same progress as TRELayer's data-draw="scroll" */
    function light() {
      var vh = window.innerHeight, r = svg.getBoundingClientRect();
      var k = R ? 1 : clamp((vh * 0.88 - r.top) / (r.height + vh * 0.45), 0, 1);
      items.forEach(function (it, j) { it.classList.toggle('is-lit', R || (k > 0.004 && k >= fr[j] - 0.004)); });
    }
    line.setAttribute('data-draw', 'scroll');
    tl.classList.add('is-live');
    build();
    L.draw(tl);
    var ticking = false;
    window.addEventListener('scroll', function () { if (ticking) return; ticking = true; requestAnimationFrame(function () { ticking = false; light(); }); }, { passive: true });
    if ('ResizeObserver' in window) new ResizeObserver(function () { build(); }).observe(list);
    else window.addEventListener('resize', build, { passive: true });
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(build);
  }

  /* ---------- the photo strip: position hairline + previous / next ---------- */
  function strip(page, R) {
    var s = $('.ab-strip', page), foot = $('.ab-strip-foot', page); if (!s || !foot) return;
    var thumb = $('.ab-strip-bar i', foot), prev = $('[data-ab-prev]', foot), next = $('[data-ab-next]', foot);
    $$('.ab-shot', s).forEach(function (f, i) { f.style.setProperty('--i', i); });
    function upd() {
      var max = s.scrollWidth - s.clientWidth, f = s.scrollWidth ? s.clientWidth / s.scrollWidth : 1, at = max > 0 ? s.scrollLeft / max : 0;
      thumb.style.setProperty('--tw', (f * 100).toFixed(2) + '%');
      thumb.style.setProperty('--tx', (f < 1 ? at * (1 - f) / f * 100 : 0).toFixed(2) + '%');
      prev.disabled = s.scrollLeft < 4; next.disabled = s.scrollLeft > max - 4;
      foot.classList.toggle('is-still', max <= 4);
    }
    function go(dir) { s.scrollBy({ left: dir * Math.max(240, s.clientWidth * 0.7), behavior: R ? 'auto' : 'smooth' }); }
    prev.addEventListener('click', function () { go(-1); });
    next.addEventListener('click', function () { go(1); });
    var t = false;
    s.addEventListener('scroll', function () { if (t) return; t = true; requestAnimationFrame(function () { t = false; upd(); }); }, { passive: true });
    window.addEventListener('resize', upd, { passive: true });
    $$('img', s).forEach(function (im) { if (!im.complete) im.addEventListener('load', upd, { once: true }); });
    upd();
  }

  /* ---------- values: icons redraw on hover; the separators are a tremor field (fine pointers, wide screens) ---------- */
  function values(page, L, R, FINE) {
    var list = $('.ab-vlist', page); if (!list) return;
    var rows = $$('.ab-val', list);
    if (R || !FINE) return;
    rows.forEach(function (row) {
      row.addEventListener('pointerenter', function () {
        if (!row.classList.contains('in') || row.__busy) return;
        row.__busy = true;
        row.classList.add('ab-redraw'); void row.offsetWidth; row.classList.remove('ab-redraw');
        setTimeout(function () { row.__busy = false; }, 1200);
      });
    });
    var cv = $('.ab-vlines', list); if (!cv || !L || !L.tremor) return;
    list.classList.add('has-lines');
    /* one line per row boundary; the canvas overhangs the list by 3% top and bottom */
    L.tremor(cv, { lines: rows.length + 1, top: 0.03 / 1.06, bottom: 1.03 / 1.06, colors: ['139,107,69'], alpha: [0.3, 0.3], width: 1,
      amp: 0, reach: 130, shiver: 5, settle: 2.2, idlePulse: 0, fade: 0, source: list });
  }

  document.addEventListener('DOMContentLoaded', function () { setTimeout(init, 0); });
})();
